# Simple BFS
from collections import deque
def is_connected(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = [False]*n
    q = deque([0])
    visited[0]=True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v]=True
                q.append(v)
    return all(visited)
print("Connected:", is_connected(edges, n))

import itertools

def max_independent_set_size(edges, n):
    edge_set = set()
    for u,v in edges:
        edge_set.add((u,v))
        edge_set.add((v,u))

    def is_independent_set(vertices):
        for i, v1 in enumerate(vertices):
            for v2 in vertices[i+1:]:
                if (v1, v2) in edge_set:
                    return False
        return True

    max_ind = 0
    for k in range(1, n+1):
        found = False
        for combo in itertools.combinations(range(n), k):
            if is_independent_set(combo):
                found = True
                break
        if found:
            max_ind = k
        else:
            break  # no independent set of size k, so max is k-1
    return max_ind

